  function upsertProfileFact({category="workflow",key,value,status="candidate",confidence=0.7,createdBy="memory-dreamer",metadata={}}){const profileKey=String(key||"").trim().slice(0,80),profileValue=String(value||"").trim().slice(0,500),safeCategory=String(category||"workflow").trim().slice(0,40);if(profileKey.length<2||profileValue.length<2)throw new Error("用户画像候选缺少有效字段");const existing=db.prepare("SELECT * FROM profile_facts WHERE workspace_id=? AND category=? AND profile_key=? AND profile_value=?").get(workspaceId,safeCategory,profileKey,profileValue),stamp=now();if(existing){db.prepare("UPDATE profile_facts SET confidence=MAX(confidence,?),evidence_count=evidence_count+1,last_seen_at=?,updated_at=? WHERE id=?").run(Number(confidence)||0.7,stamp,stamp,existing.id);return normalizeProfile(db.prepare("SELECT * FROM profile_facts WHERE id=?").get(existing.id));}const id=uid("prf");db.prepare("INSERT INTO profile_facts VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)").run(id,workspaceId,safeCategory,profileKey,profileValue,status,Number(confidence)||0.7,1,stamp,createdBy,JSON.stringify(metadata),stamp,stamp);return normalizeProfile(db.prepare("SELECT * FROM profile_facts WHERE id=?").get(id));}
