  function saveSystemPromptDraft({promptKey="personal-assistant",content,summary="人工编辑"}){const body=String(content||"").trim();if(body.length<300)throw new Error("系统提示词过短，至少需要 300 个字符");if(body.length>30000)throw new Error("系统提示词不能超过 30000 个字符");const version=Number(db.prepare("SELECT MAX(version) version FROM system_prompt_versions WHERE prompt_key=?").get(promptKey)?.version||0)+1,id=uid("prompt"),stamp=now();db.prepare("INSERT INTO system_prompt_versions(id,prompt_key,version,status,content,change_summary,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?)").run(id,promptKey,version,"draft",body,String(summary||"人工编辑").slice(0,300),"local-owner",stamp,stamp);return db.prepare("SELECT * FROM system_prompt_versions WHERE id=?").get(id);}
  function publishSystemPromptVersion(versionId){const target=db.prepare("SELECT * FROM system_prompt_versions WHERE id=?").get(versionId);if(!target)throw new Error("系统提示词版本不存在");if(!["draft","archived"].includes(target.status))throw new Error("该系统提示词版本不能发布");db.exec("BEGIN IMMEDIATE");try{db.prepare("UPDATE system_prompt_versions SET status='archived',updated_at=? WHERE prompt_key=? AND status='published'").run(now(),target.prompt_key);db.prepare("UPDATE system_prompt_versions SET status='published',updated_at=? WHERE id=?").run(now(),versionId);db.exec("COMMIT");}catch(error){db.exec("ROLLBACK");throw error;}return systemPromptOverview(target.prompt_key);}
