  function startRun({sessionId,source,input,context,model,taskId=null}){const runId=uid("run"),stamp=now(),safeInput=redact(String(input)).slice(0,500000),safeContext=redact(JSON.stringify(context)).slice(0,1000000);db.prepare("INSERT INTO agent_runs(id,session_id,source,status,model_config_id,provider,model_id,input_text,context_json,output_text,error,trace_json,input_chars,output_chars,latency_ms,created_at,updated_at,task_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)").run(runId,sessionId||null,source,"running",model?.id||null,model?.provider||null,model?.model_id||null,safeInput,safeContext,null,null,"[]",safeInput.length,0,null,stamp,stamp,taskId);return{runId,startedAt:Date.now(),taskId};}
