  function toggleCapability(id,enabled){if(id==="plugin_sqlite"&&!enabled)throw new Error("sqlite-store 是系统事实库，运行期间不能停用");const current=db.prepare("SELECT * FROM capability_registry WHERE id=?").get(id);if(!current)return null;const capabilityConfig=parse(current.config_json);if(enabled&&current.kind==="plugin"&&capabilityConfig.status==="downloaded"&&capabilityConfig.compatibility!=="verified")throw new Error("该社区插件尚未通过当前 Harness 版本与权限验证，不能直接启用");db.prepare("UPDATE capability_registry SET enabled=?,updated_at=? WHERE id=?").run(enabled?1:0,now(),id);return db.prepare("SELECT * FROM capability_registry WHERE id=?").get(id);}
  function skillDetail(skillId){const skill=db.prepare("SELECT * FROM capability_registry WHERE id=? AND kind='skill'").get(skillId);if(!skill)return null;const versions=db.prepare("SELECT * FROM skill_versions WHERE skill_id=? ORDER BY created_at DESC").all(skillId).map(normalizeVersion);const evolutions=db.prepare("SELECT * FROM skill_evolution_runs WHERE skill_id=? ORDER BY created_at DESC LIMIT 20").all(skillId).map((r)=>({...r,source_run_ids:parse(r.source_run_ids_json,[])}));const usage=db.prepare("SELECT COUNT(*) calls,SUM(CASE WHEN status='failed' THEN 1 ELSE 0 END) failures,AVG(latency_ms) avg_latency FROM agent_runs WHERE source IN (SELECT value FROM json_each(?))").get(JSON.stringify(skillSources(skill.name)));return{...skill,config:parse(skill.config_json),versions,evolutions,usage};}
